#!/usr/bin/env python3
"""Underline all headlines (all-caps section titles) in an unpacked docx document.xml."""
import sys
import xml.dom.minidom as minidom

path = sys.argv[1] if len(sys.argv) > 1 else "unpacked_report/word/document.xml"
dom = minidom.parse(path)

W = "w:u"
PARAGRAPH = "w:p"
RUN = "w:r"
RPR = "w:rPr"
TEXT = "w:t"


def para_text(p):
    parts = []
    for t in p.getElementsByTagName(TEXT):
        if t.firstChild:
            parts.append(t.firstChild.data)
    return "".join(parts)


def is_headline(text):
    """Headline = non-empty paragraph whose alphabetic chars are all uppercase."""
    stripped = text.strip()
    if not stripped:
        return False
    has_alpha = any(c.isalpha() for c in stripped)
    if not has_alpha:
        return False
    return all(not c.isalpha() or c.isupper() for c in stripped)


headlines = []
for p in dom.getElementsByTagName(PARAGRAPH):
    text = para_text(p)
    if not is_headline(text):
        continue
    headlines.append(text)
    for r in p.getElementsByTagName(RUN):
        rPrs = r.getElementsByTagName(RPR)
        if rPrs:
            rPr = rPrs[0]
        else:
            rPr = dom.createElement(RPR)
            r.insertBefore(rPr, r.firstChild)
        if not rPr.getElementsByTagName(W):
            u = dom.createElement(W)
            u.setAttribute("w:val", "single")
            rPr.appendChild(u)

print(f"Underlined {len(headlines)} headline(s):")
for h in headlines:
    print("  -", h)

with open(path, "wb") as f:
    f.write(dom.toprettyxml(indent="  ", encoding="ascii"))
print(f"Saved {path}")

#!/usr/bin/env python3
"""Pack an unpacked docx directory back into a .docx file (stdlib version)."""
import shutil
import subprocess
import sys
import tempfile
import xml.dom.minidom
import zipfile
from pathlib import Path


def condense_xml(xml_file):
    """Strip unnecessary whitespace and remove comments."""
    with open(xml_file, "r", encoding="utf-8") as f:
        dom = xml.dom.minidom.parse(f)
    for element in dom.getElementsByTagName("*"):
        if element.tagName.endswith(":t"):
            continue
        for child in list(element.childNodes):
            if (
                child.nodeType == child.TEXT_NODE
                and child.nodeValue
                and child.nodeValue.strip() == ""
            ) or child.nodeType == child.COMMENT_NODE:
                element.removeChild(child)
    with open(xml_file, "wb") as f:
        f.write(dom.toxml(encoding="UTF-8"))


def validate_document(doc_path):
    """Validate by converting to HTML with soffice; skip if soffice missing."""
    with tempfile.TemporaryDirectory() as temp_dir:
        try:
            result = subprocess.run(
                [
                    "soffice",
                    "--headless",
                    "--convert-to",
                    "html:HTML",
                    "--outdir",
                    temp_dir,
                    str(doc_path),
                ],
                capture_output=True,
                timeout=60,
                text=True,
            )
            if not (Path(temp_dir) / f"{doc_path.stem}.html").exists():
                print(f"Validation error: {result.stderr.strip() or 'conversion failed'}", file=sys.stderr)
                return False
            return True
        except FileNotFoundError:
            print("Warning: soffice not found. Skipping validation.", file=sys.stderr)
            return True
        except subprocess.TimeoutExpired:
            print("Validation error: Timeout during conversion", file=sys.stderr)
            return False
        except Exception as e:
            print(f"Validation error: {e}", file=sys.stderr)
            return False


def main():
    input_dir, output_file = Path(sys.argv[1]), Path(sys.argv[2])
    if not input_dir.is_dir():
        sys.exit(f"Error: {input_dir} is not a directory")
    if output_file.suffix.lower() != ".docx":
        sys.exit("Error: output file must be a .docx file")

    with tempfile.TemporaryDirectory() as temp_dir:
        temp_content_dir = Path(temp_dir) / "content"
        shutil.copytree(input_dir, temp_content_dir)

        for pattern in ["*.xml", "*.rels"]:
            for xml_file in temp_content_dir.rglob(pattern):
                condense_xml(xml_file)

        output_file.parent.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(output_file, "w", zipfile.ZIP_DEFLATED) as zf:
            for f in temp_content_dir.rglob("*"):
                if f.is_file():
                    zf.write(f, f.relative_to(temp_content_dir))

        if not validate_document(output_file):
            output_file.unlink()
            sys.exit("Contents would produce a corrupt file.")
    print(f"Packed {output_file}")


if __name__ == "__main__":
    main()

